#include <stdio.h>
struct stu {
  int num;
  char name[20];
  int score;
};
int main(void)
{
  struct stu s[50], t;
  int n = 0, i, j;
  FILE *fp = fopen("stu.txt", "r");
  if (fp == NULL) {
    printf("cannot open\n");
    return 1;
  }
  while (n < 50) {
    if (fscanf(fp, "%d%19s%d", &s[n].num,
               s[n].name, &s[n].score) != 3)
      break;
    n++;
  }
  fclose(fp);
  for (i = 0; i < n - 1; i++)
    for (j = 0; j < n - 1 - i; j++)
      if (s[j].score < s[j + 1].score ||
          (s[j].score == s[j + 1].score &&
           s[j].num > s[j + 1].num)) {
        t = s[j]; s[j] = s[j + 1]; s[j + 1] = t;
      }
  fp = fopen("sorted.txt", "w");
  if (fp == NULL) return 1;
  for (i = 0; i < n; i++)
    fprintf(fp, "%d %s %d\n", s[i].num, s[i].name,
            s[i].score);
  fclose(fp);
  printf("%d\n", n);
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
typedef struct node {
  int data;
  struct node *next;
} NODE;
int main(void)
{
  NODE head, *tail = &head, *p, *q;
  int x, first = 1;
  head.next = NULL;
  while (scanf("%d", &x) == 1 && x != 0) {
    p = (NODE *)malloc(sizeof(NODE));
    if (p == NULL) return 1;
    p->data = x;
    p->next = NULL;
    tail->next = p;
    tail = p;
  }
  scanf("%d", &x);
  q = &head;
  while (q->next != NULL) {
    p = q->next;
    if (p->data == x) {
      q->next = p->next;
      free(p);
    } else
      q = p;
  }
  if (head.next == NULL) printf("empty");
  for (p = head.next; p != NULL; p = q) {
    printf(first ? "%d" : " %d", p->data);
    first = 0;
    q = p->next;
    free(p);
  }
  printf("\n");
  return 0;
}

#include <stdio.h>
void compress(char *s, char *t)
{
  int n;
  while (*s != '\0') {
    n = 1;
    while (s[n] == s[0])
      n++;
    *t++ = s[0];
    if (n >= 10)
      *t++ = n / 10 + '0';
    *t++ = n % 10 + '0';
    s += n;
  }
  *t = '\0';
}
int main(void)
{
  char s[81], t[161];
  scanf("%80s", s);
  compress(s, t);
  printf("%s\n", t);
  return 0;
}

